<body>
<canvas id="bgCanvas"></canvas>
<div id="score">Счёт: 0</div>
<canvas id="game" width="400" height="400"></canvas>
<div id="message"></div>
<div id="gameOverOverlay">
    <div class="overlay-content">
        <h1>GAME OVER</h1>
        <div class="final-score" id="finalScore"></div>
        <div class="restart-hint">Нажмите R или Пробел для перезапуска</div>
    </div>
</div>
<script>
const canvas = document.getElementById('game');
const ctx = canvas.getContext('2d');
const scoreEl = document.getElementById('score');
const messageEl = document.getElementById('message');
const overlay = document.getElementById('gameOverOverlay');
const finalScoreEl = document.getElementById('finalScore');
const bgCanvas = document.getElementById('bgCanvas');
const bgCtx = bgCanvas.getContext('2d');

bgCanvas.width = window.innerWidth;
bgCanvas.height = window.innerHeight;
window.addEventListener('resize', () => {
    bgCanvas.width = window.innerWidth;
    bgCanvas.height = window.innerHeight;
});

const GRID = 20;
const COLS = canvas.width / GRID;
const ROWS = canvas.height / GRID;
const TICK = 120;

let snake, direction, nextDirection, food, score, alive, intervalId;
let particles = [];
let bgStars = [];
let foodPulse = 0;
let foodSpawnAnim = 0;
let scorePopTimer = 0;
let gameOverAnim = 0;
let trailPoints = [];

// Background stars
for (let i = 0; i < 80; i++) {
    bgStars.push({
        x: Math.random() * bgCanvas.width,
        y: Math.random() * bgCanvas.height,
        r: Math.random() * 1.5 + 0.5,
        speed: Math.random() * 0.3 + 0.1,
        alpha: Math.random() * 0.5 + 0.2,
        twinkleSpeed: Math.random() * 0.02 + 0.005,
        twinklePhase: Math.random() * Math.PI * 2
    });
}

function init() {
    const mid = Math.floor(COLS / 2);
    snake = [
        { x: mid, y: Math.floor(ROWS / 2) },
        { x: mid - 1, y: Math.floor(ROWS / 2) },
        { x: mid - 2, y: Math.floor(ROWS / 2) }
    ];
    direction = { x: 1, y: 0 };
    nextDirection = { x: 1, y: 0 };
    score = 0;
    alive = true;
    scoreEl.textContent = 'Счёт: 0';
    scoreEl.classList.remove('pop');
    messageEl.textContent = '';
    particles = [];
    trailPoints = [];
    foodSpawnAnim = 0;
    gameOverAnim = 0;
    overlay.classList.remove('active');
    canvas.classList.remove('shake');
    placeFood();
    if (intervalId) clearInterval(intervalId);
    intervalId = setInterval(tick, TICK);
}

function placeFood() {
    let pos;
    let attempts = 0;
    do {
        pos = {
            x: Math.floor(Math.random() * COLS),
            y: Math.floor(Math.random() * ROWS)
        };
        attempts++;
    } while (snake.some(s => s.x === pos.x && s.y === pos.y) && attempts < 500);
    food = pos;
    foodSpawnAnim = 1.0;
}

function spawnParticles(x, y) {
    const colors = ['#e94560', '#ff6b8a', '#ffb347', '#ffd700', '#ff4757', '#ff6348'];
    for (let i = 0; i < 20; i++) {
        const angle = Math.random() * Math.PI * 2;
        const speed = Math.random() * 4 + 1.5;
        particles.push({
            x: x * GRID + GRID / 2,
            y: y * GRID + GRID / 2,
            vx: Math.cos(angle) * speed,
            vy: Math.sin(angle) * speed,
            life: 1.0,
            decay: Math.random() * 0.025 + 0.015,
            size: Math.random() * 4 + 2,
            color: colors[Math.floor(Math.random() * colors.length)],
            type: 'circle'
        });
    }
    // Ring particles
    for (let i = 0; i < 12; i++) {
        const angle = (i / 12) * Math.PI * 2;
        const speed = 3;
        particles.push({
            x: x * GRID + GRID / 2,
            y: y * GRID + GRID / 2,
            vx: Math.cos(angle) * speed,
            vy: Math.sin(angle) * speed,
            life: 1.0,
            decay: 0.02,
            size: 3,
            color: '#ffd700',
            type: 'ring'
        });
    }
}

function tick() {
    if (!alive) return;

    direction = { ...nextDirection };

    const head = {
        x: snake[0].x + direction.x,
        y: snake[0].y + direction.y
    };

    if (head.x < 0 || head.x >= COLS || head.y < 0 || head.y >= ROWS) {
        return gameOver();
    }

    if (snake.some(s => s.x === head.x && s.y === head.y)) {
        return gameOver();
    }

    snake.unshift(head);

    if (head.x === food.x && head.y === food.y) {
        score += 10;
        scoreEl.textContent = 'Счёт: ' + score;
        scoreEl.classList.remove('pop');
        void scoreEl.offsetWidth;
        scoreEl.classList.add('pop');
        scorePopTimer = 300;
        spawnParticles(food.x, food.y);
        placeFood();
    } else {
        const tail = snake.pop();
        trailPoints.push({ x: tail.x * GRID + GRID / 2, y: tail.y * GRID + GRID / 2, life: 1.0 });
    }

    draw();
}

function gameOver() {
    alive = false;
    clearInterval(intervalId);
    gameOverAnim = 1;
    overlay.classList.add('active');
    finalScoreEl.textContent = 'Ваш счёт: ' + score;
    messageEl.textContent = 'Game Over! Нажмите R или Пробел для перезапуска.';
    canvas.classList.add('shake');
    setTimeout(() => canvas.classList.remove('shake'), 500);

    // Death particles
    snake.forEach((seg, i) => {
        setTimeout(() => {
            for (let j = 0; j < 5; j++) {
                const angle = Math.random() * Math.PI * 2;
                const speed = Math.random() * 3 + 1;
                particles.push({
                    x: seg.x * GRID + GRID / 2,
                    y: seg.y * GRID + GRID / 2,
                    vx: Math.cos(angle) * speed,
                    vy: Math.sin(angle) * speed,
                    life: 1.0,
                    decay: 0.015,
                    size: Math.random() * 3 + 1,
                    color: '#e94560',
                    type: 'circle'
                });
            }
        }, i * 30);
    });
}

function draw() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // Subtle grid
    ctx.strokeStyle = 'rgba(255,255,255,0.025)';
    ctx.lineWidth = 1;
    for (let i = 0; i <= COLS; i++) {
        ctx.beginPath();
        ctx.moveTo(i * GRID, 0);
        ctx.lineTo(i * GRID, canvas.height);
        ctx.stroke();
    }
    for (let i = 0; i <= ROWS; i++) {
        ctx.beginPath();
        ctx.moveTo(0, i * GRID);
        ctx.lineTo(canvas.width, i * GRID);
        ctx.stroke();
    }

    // Trail points
    trailPoints.forEach(tp => {
        ctx.fillStyle = `rgba(83, 215, 105, ${tp.life * 0.15})`;
        ctx.beginPath();
        ctx.arc(tp.x, tp.y, GRID / 3 * tp.life, 0, Math.PI * 2);
        ctx.fill();
    });

    // Food with glow and pulse
    foodPulse += 0.05;
    const pulse = Math.sin(foodPulse) * 0.3 + 0.7;
    const spawnScale = foodSpawnAnim > 0 ? 1 + (1 - foodSpawnAnim) * 0.5 : 1;
    const foodAlpha = foodSpawnAnim > 0 ? foodSpawnAnim : 1;

    // Outer glow
    const glowSize = 20 * pulse;
    const gradient = ctx.createRadialGradient(
        food.x * GRID + GRID / 2, food.y * GRID + GRID / 2, 2,
        food.x * GRID + GRID / 2, food.y * GRID + GRID / 2, glowSize + 10
    );
    gradient.addColorStop(0, `rgba(233, 69, 96, ${0.4 * pulse * foodAlpha})`);
    gradient.addColorStop(0.5, `rgba(233, 69, 96, ${0.15 * pulse * foodAlpha})`);
    gradient.addColorStop(1, 'rgba(233, 69, 96, 0)');
    ctx.fillStyle = gradient;
    ctx.beginPath();
    ctx.arc(food.x * GRID + GRID / 2, food.y * GRID + GRID / 2, glowSize + 10, 0, Math.PI * 2);
    ctx.fill();

    // Food body
    ctx.fillStyle = `rgba(233, 69, 96, ${foodAlpha})`;
    ctx.shadowColor = '#e94560';
    ctx.shadowBlur = 15 * pulse;
    ctx.beginPath();
    ctx.arc(
        food.x * GRID + GRID / 2,
        food.y * GRID + GRID / 2,
        (GRID / 2 - 2) * spawnScale,
        0, Math.PI * 2
    );
    ctx.fill();
    ctx.shadowBlur = 0;

    // Food highlight
    ctx.fillStyle = `rgba(255, 255, 255, ${0.3 * pulse * foodAlpha})`;
    ctx.beginPath();
    ctx.arc(
        food.x * GRID + GRID / 2 - 2,
        food.y * GRID + GRID / 2 - 2,
        (GRID / 4 - 1) * spawnScale,
        0, Math.PI * 2
    );
    ctx.fill();

    // Snake with gradient and glow
    const len = snake.length;
    snake.forEach((seg, i) => {
        const t = i / Math.max(len - 1, 1);
        const r = Math.floor(30 + 53 * (1 - t));
        const g = Math.floor(180 + 75 * (1 - t));
        const b = Math.floor(80 + 125 * (1 - t));
        const alpha = 1 - t * 0.3;

        const pad = i === 0 ? 1 : 2;
        const radius = i === 0 ? 5 : 4;
        const x = seg.x * GRID + pad;
        const y = seg.y * GRID + pad;
        const w = GRID - pad * 2;
        const h = GRID - pad * 2;

        // Glow for head
        if (i === 0) {
            ctx.shadowColor = '#53d769';
            ctx.shadowBlur = 12;
        }

        // Gradient fill
        const bodyGrad = ctx.createLinearGradient(x, y, x + w, y + h);
        bodyGrad.addColorStop(0, `rgba(${r}, ${g}, ${b}, ${alpha})`);
        bodyGrad.addColorStop(1, `rgba(${Math.floor(r * 0.7)}, ${Math.floor(g * 0.85)}, ${Math.floor(b * 0.7)}, ${alpha})`);
        ctx.fillStyle = bodyGrad;

        ctx.beginPath();
        ctx.moveTo(x + radius, y);
        ctx.lineTo(x + w - radius, y);
        ctx.quadraticCurveTo(x + w, y, x + w, y + radius);
        ctx.lineTo(x + w, y + h - radius);
        ctx.quadraticCurveTo(x + w, y + h, x + w - radius, y + h);
        ctx.lineTo(x + radius, y + h);
        ctx.quadraticCurveTo(x, y + h, x, y + h - radius);
        ctx.lineTo(x, y + radius);
        ctx.quadraticCurveTo(x, y, x + radius, y);
        ctx.closePath();
        ctx.fill();
        ctx.shadowBlur = 0;

        // Scale pattern on body
        if (i > 0 && i % 2 === 0) {
            ctx.fillStyle = `rgba(255, 255, 255, 0.06)`;
            ctx.beginPath();
            ctx.arc(seg.x * GRID + GRID / 2, seg.y * GRID + GRID / 2, GRID / 4, 0, Math.PI * 2);
            ctx.fill();
        }
    });

    // Eyes on head
    const head = snake[0];
    const cx = head.x * GRID + GRID / 2;
    const cy = head.y * GRID + GRID / 2;
    const eyeOff = 4;
    let e1x, e1y, e2x, e2y;
    if (direction.x === 1) {
        e1x = cx + 3; e1y = cy - eyeOff;
        e2x = cx + 3; e2y = cy + eyeOff;
    } else if (direction.x === -1) {
        e1x = cx - 3; e1y = cy - eyeOff;
        e2x = cx - 3; e2y = cy + eyeOff;
    } else if (direction.y === -1) {
        e1x = cx - eyeOff; e1y = cy - 3;
        e2x = cx + eyeOff; e2y = cy - 3;
    } else {
        e1x = cx - eyeOff; e1y = cy + 3;
        e2x = cx + eyeOff; e2y = cy + 3;
    }
    // Eye whites
    ctx.fillStyle = '#fff';
    ctx.shadowColor = '#fff';
    ctx.shadowBlur = 4;
    ctx.beginPath(); ctx.arc(e1x, e1y, 2.8, 0, Math.PI * 2); ctx.fill();
    ctx.beginPath(); ctx.arc(e2x, e2y, 2.8, 0, Math.PI * 2); ctx.fill();
    ctx.shadowBlur = 0;
    // Pupils
    ctx.fillStyle = '#111';
    ctx.beginPath(); ctx.arc(e1x + direction.x * 0.8, e1y + direction.y * 0.8, 1.5, 0, Math.PI * 2); ctx.fill();
    ctx.beginPath(); ctx.arc(e2x + direction.x * 0.8, e2y + direction.y * 0.8, 1.5, 0, Math.PI * 2); ctx.fill();
}

function drawBackground() {
    bgCtx.clearRect(0, 0, bgCanvas.width, bgCanvas.height);

    // Gradient background
    const bgGrad = bgCtx.createRadialGradient(
        bgCanvas.width / 2, bgCanvas.height / 2, 50,
        bgCanvas.width / 2, bgCanvas.height / 2, bgCanvas.width * 0.7
    );
    bgGrad.addColorStop(0, '#1a1a2e');
    bgGrad.addColorStop(1, '#0a0a1a');
    bgCtx.fillStyle = bgGrad;
    bgCtx.fillRect(0, 0, bgCanvas.width, bgCanvas.height);

    // Stars
    const time = Date.now() * 0.001;
    bgStars.forEach(star => {
        const twinkle = Math.sin(time * star.twinkleSpeed * 60 + star.twinklePhase) * 0.3 + 0.7;
        bgCtx.fillStyle = `rgba(255, 255, 255, ${star.alpha * twinkle})`;
        bgCtx.beginPath();
        bgCtx.arc(star.x, star.y, star.r, 0, Math.PI * 2);
        bgCtx.fill();
    });
}

function updateParticles() {
    for (let i = particles.length - 1; i >= 0; i--) {
        const p = particles[i];
        p.x += p.vx;
        p.y += p.vy;
        p.vx *= 0.97;
        p.vy *= 0.97;
        p.vy += 0.05;
        p.life -= p.decay;
        if (p.life <= 0) {
            particles.splice(i, 1);
        }
    }

    for (let i = trailPoints.length - 1; i >= 0; i--) {
        trailPoints[i].life -= 0.04;
        if (trailPoints[i].life <= 0) {
            trailPoints.splice(i, 1);
        }
    }

    if (foodSpawnAnim > 0) {
        foodSpawnAnim -= 0.04;
        if (foodSpawnAnim < 0) foodSpawnAnim = 0;
    }

    if (scorePopTimer > 0) {
        scorePopTimer -= 16;
        if (scorePopTimer <= 0) {
            scoreEl.classList.remove('pop');
        }
    }
}

function drawParticles() {
    particles.forEach(p => {
        ctx.globalAlpha = p.life;
        ctx.fillStyle = p.color;
        ctx.shadowColor = p.color;
        ctx.shadowBlur = 6;

        if (p.type === 'ring') {
            ctx.beginPath();
            ctx.arc(p.x, p.y, p.size * (2 - p.life), 0, Math.PI * 2);
            ctx.stroke();
        } else {
            ctx.beginPath();
            ctx.arc(p.x, p.y, p.size * p.life, 0, Math.PI * 2);
            ctx.fill();
        }
        ctx.shadowBlur = 0;
    });
    ctx.globalAlpha = 1;
}

function gameLoop() {
    drawBackground();
    updateParticles();
    if (alive) {
        draw();
        drawParticles();
    } else {
        draw();
        drawParticles();
    }
    requestAnimationFrame(gameLoop);
}

document.addEventListener('keydown', e => {
    if (!alive && (e.key === 'r' || e.key === 'R' || e.key === ' ' || e.key === 'Space')) {
        e.preventDefault();
        init();
        return;
    }

    const key = e.key;
    if (
        (key === 'ArrowUp' || key === 'w' || key === 'W' || key === 'ц' || key === 'Ц') && direction.y !== 1 ||
        (key === 'ArrowDown' || key === 's' || key === 'S' || key === 'ы' || key === 'Ы') && direction.y !== -1 ||
        (key === 'ArrowLeft' || key === 'a' || key === 'A' || key === 'ф' || key === 'Ф') && direction.x !== 1 ||
        (key === 'ArrowRight' || key === 'd' || key === 'D' || key === 'в' || key === 'В') && direction.x !== -1
    ) {
        e.preventDefault();
    }

    if (key === 'ArrowUp' || key === 'w' || key === 'W' || key === 'ц' || key === 'Ц') {
        nextDirection = { x: 0, y: -1 };
    } else if (key === 'ArrowDown' || key === 's' || key === 'S' || key === 'ы' || key === 'Ы') {
        nextDirection = { x: 0, y: 1 };
    } else if (key === 'ArrowLeft' || key === 'a' || key === 'A' || key === 'ф' || key === 'Ф') {
        nextDirection = { x: -1, y: 0 };
    } else if (key === 'ArrowRight' || key === 'd' || key === 'D' || key === 'в' || key === 'В') {
        nextDirection = { x: 1, y: 0 };
    }
});

init();
gameLoop();
</script>
</body>
</html>
